//! 🏠️ One resident Source clock keeps its original action, producer, decision and retirement custody.
use super::*;
use semio_framework_value_control_contract::{OriginalWorkActionIdentity,RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll};
use semio_framework_value_retirement::{OriginalRetirementFailure,OriginalRetirementPoll,RetirementDemand};
use std::mem::{size_of,ManuallyDrop};
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
/// 🧳️ Holds every real Source clock owner and recorded reply across interruption.
pub struct OriginalSourceClock{owner:ManuallyDrop<Option<Box<dyn OriginalErasedHostClock>>>,action:ManuallyDrop<Option<OriginalClockAction>>,decision:ManuallyDrop<OriginalClockDecisionFrame>,deadline:Option<OriginalClockDeadline>,reading:ManuallyDrop<Option<Result<OriginalClockObservation,ValueError>>>,refusal:ManuallyDrop<Option<ValueError>>,reading_transferred:bool,action_turn:Option<OriginalSourceTurnIdentity>,decision_turn:Option<OriginalSourceTurnIdentity>,retirement_action:Option<(semio_framework_value_control_contract::OriginalEffectInvocationIdentity,RetainedCloneGrant,u64)>}
impl OriginalSourceClock{
 /// 🌱️ Creates an empty inline Source owner without admitting a producer.
 pub fn new()->Self{Self{owner:ManuallyDrop::new(None),action:ManuallyDrop::new(None),decision:ManuallyDrop::new(OriginalClockDecisionFrame::new()),deadline:None,reading:ManuallyDrop::new(None),refusal:ManuallyDrop::new(None),reading_transferred:false,action_turn:None,decision_turn:None,retirement_action:None}}
 /// 🈳️ Reports whether all producer, action and refusal custody has returned.
 pub fn terminal_is_empty(&self)->bool{self.owner.is_none()&&self.action.is_none()&&self.decision.terminal_is_empty()&&self.deadline.is_none()&&self.reading.is_none()&&self.refusal.is_none()&&!self.reading_transferred&&self.action_turn.is_none()&&self.decision_turn.is_none()&&self.retirement_action.is_none()}
 fn check(&self,c:&OriginalSystemClockContext<'_>)->Result<(),ValueError>{let owner=self.owner.as_ref().ok_or_else(||refusal("original Source clock is absent"))?;if owner.validate_source(c)?!=Some(c.source_turn()){return Err(invalid())}Ok(())}
 /// 🎟️ Admits the original host directly into the Source-owned slot.
 pub fn admit<P:OriginalHostClockProducer+semio_framework_value_retirement::retirement::RetireOwned+Send+'static>(&mut self,c:&OriginalSystemClockContext<'_>,host:&mut Option<OriginalClockAuthority<OriginalHostClock<P>>>,effect:&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if !self.terminal_is_empty(){return fail(refusal("original Source clock slot is occupied"))}if effect.work_source_turn()!=Some(c.source_turn()){return fail(invalid())}let Some(authority)=host.as_ref()else{return fail(refusal("original host clock is absent"))};if let Err(error)=authority.source_turn(c){return fail(error)}admit_original_host_clock(host,&mut self.owner,effect)}
 /// 📏️ Quotes the actual producer before a new action.
 pub fn demand(&self,c:&OriginalSystemClockContext<'_>)->Result<OriginalClockDemand,ValueError>{self.check(c)?;self.owner.as_ref().ok_or_else(invalid)?.demand(c)}
 /// 📨️ Drives or recovers the same Source and Work action.
 pub fn poll_reading(&mut self,c:&mut OriginalSystemClockContext<'_>,effect:&mut RetainedAllocationEffect<'_>,fuel:u64)->Result<OriginalClockDecisionStatus,ValueError>{use OriginalClockDecisionStatus as Status;self.check(c)?;let turn=c.source_turn();if self.decision_turn.is_some()||self.action_turn.is_some_and(|prior|prior!=turn){return Err(invalid())}if self.refusal.is_some(){return Ok(Status::Refused)}if self.reading_transferred{return Err(refusal("original clock reading awaits finish"))}if self.reading.is_some(){return Ok(Status::Ready)}let quote=match self.owner.as_ref().ok_or_else(invalid)?.demand(c){Ok(quote)=>quote,Err(error)=>{self.action_turn=Some(turn);*self.refusal=Some(error);return Ok(Status::Refused)}};if self.action.is_none()&&fuel<quote.work{return Ok(Status::Pending)}self.action_turn=Some(turn);let Self{owner,action,reading,refusal,..}=self;match owner.as_mut().ok_or_else(invalid)?.drive(c,effect,action){Err(error)=>{**refusal=Some(error);Ok(Status::Refused)},Ok(false)=>{if let Some(action)=action.as_mut(){action.transfer_refusal(refusal)?;}Ok(if refusal.is_some(){Status::Refused}else{Status::Pending})},Ok(true)=>{let action=action.as_mut().ok_or_else(invalid)?;if action.transfer_reading(reading)?{Ok(Status::Ready)}else{Ok(Status::Pending)}}}}
 /// 📤️ Moves the exact reading to an empty caller-owned slot.
 pub fn take_reading(&mut self,c:&OriginalSystemClockContext<'_>,output:&mut Option<Result<OriginalClockObservation,ValueError>>)->Result<bool,ValueError>{self.check(c)?;if output.is_some()||self.action_turn!=Some(c.source_turn()){return Err(invalid())}let Some(reading)=self.reading.take()else{return Ok(false)};*output=Some(reading);self.reading_transferred=true;Ok(true)}
 /// 🏁️ Finishes the exact action after its reading transfers.
 pub fn finish_reading(&mut self,c:&OriginalSystemClockContext<'_>)->Result<(),ValueError>{self.check(c)?;if self.action_turn!=Some(c.source_turn())||!self.reading_transferred||self.refusal.is_some(){return Err(invalid())}self.owner.as_mut().ok_or_else(invalid)?.finish(c,&mut self.action)?;self.reading_transferred=false;self.action_turn=None;Ok(())}
 /// 📤️ Moves the exact retained refusal to an empty caller slot.
 pub fn take_refusal(&mut self,c:&OriginalSystemClockContext<'_>,output:&mut Option<ValueError>)->Result<bool,ValueError>{self.check(c)?;if output.is_some()||self.action_turn.or(self.decision_turn)!=Some(c.source_turn()){return Err(invalid())}let Some(error)=self.refusal.take()else{return Ok(false)};*output=Some(error);Ok(true)}
 /// ↩️ Cancels only a same-Source reading whose producer never started.
 pub fn cancel_unstarted_reading(&mut self,c:&OriginalSystemClockContext<'_>)->Result<(),ValueError>{self.check(c)?;if self.action_turn!=Some(c.source_turn())||self.action.is_some()||self.reading.is_some()||self.refusal.is_some()||self.reading_transferred{return Err(invalid())}self.action_turn=None;Ok(())}
 /// 🎯️ Derives a deadline from this actual producer original observation.
 pub fn deadline(&mut self,c:&OriginalSystemClockContext<'_>,observation:OriginalClockObservation,duration:u64)->Result<OriginalClockDeadline,ValueError>{self.check(c)?;if self.deadline.is_some(){return Err(refusal("original Source deadline is already bound"))}let deadline=self.owner.as_ref().ok_or_else(invalid)?.deadline_from(c,observation,duration)?;self.deadline=Some(deadline);Ok(deadline)}
 /// 🚦️ Retains the same immutable deadline decision through Pending and unwind.
 pub fn poll_decision(&mut self,c:&mut OriginalSystemClockContext<'_>,effect:&mut RetainedAllocationEffect<'_>,deadline:OriginalClockDeadline,fuel:u64)->Result<OriginalClockDecisionStatus,ValueError>{use OriginalClockDecisionStatus as Status;self.check(c)?;let turn=c.source_turn();if self.deadline!=Some(deadline){return Err(refusal("original Source deadline changed"))}if self.action_turn.is_some()||self.decision_turn.is_some_and(|prior|prior!=turn){return Err(invalid())}if self.refusal.is_some(){return Ok(Status::Refused)}if fuel>0{let quote=match self.owner.as_ref().ok_or_else(invalid)?.demand(c){Ok(quote)=>quote,Err(error)=>{self.decision_turn=Some(turn);*self.refusal=Some(error);return Ok(Status::Refused)}};if self.decision.terminal_is_empty()&&fuel<quote.work{return Ok(Status::Pending)}}self.decision_turn=Some(turn);let Self{owner,decision,refusal,..}=self;match owner.as_mut().ok_or_else(invalid)?.poll_decision(c,effect,decision,deadline,fuel){Ok(Status::Refused)=>{decision.transfer_refusal(refusal)?;Ok(Status::Refused)},Ok(status)=>Ok(status),Err(error)=>{**refusal=Some(error);Ok(Status::Refused)}}}
 /// 🛂️ Checks the same resident recorded decision against the genuine current fuel.
 pub fn allows(&self,c:&OriginalSystemClockContext<'_>,fuel:u64)->Result<bool,ValueError>{self.check(c)?;if self.decision_turn!=Some(c.source_turn())||self.decision.request.map(|request|request.0)!=self.deadline{return Err(invalid())}if self.refusal.is_some()||self.decision.transferred||self.decision.failed{return Ok(false)}if self.decision.last_fuel.is_some_and(|prior|fuel>prior){return Err(invalid())}Ok(fuel>0&&self.decision.decision==Some(false))}
 /// 📤️ Moves the exact decision to an empty caller slot.
 pub fn take_decision(&mut self,c:&OriginalSystemClockContext<'_>,fuel:u64,output:&mut Option<bool>)->Result<bool,ValueError>{self.check(c)?;if self.decision_turn!=Some(c.source_turn()){return Err(invalid())}self.decision.transfer_decision(fuel,output)}
 /// 🏁️ Finishes the same original decision after transfer.
 pub fn finish_decision(&mut self,c:&OriginalSystemClockContext<'_>)->Result<(),ValueError>{self.check(c)?;if self.decision_turn!=Some(c.source_turn())||self.refusal.is_some(){return Err(invalid())}self.owner.as_mut().ok_or_else(invalid)?.finish_decision(c,&mut self.decision)?;self.decision_turn=None;Ok(())}
 /// ↩️ Cancels only a decision whose original producer never started.
 pub fn cancel_unstarted_decision(&mut self,c:&OriginalSystemClockContext<'_>)->Result<(),ValueError>{self.check(c)?;if self.decision_turn!=Some(c.source_turn())||self.refusal.is_some(){return Err(invalid())}self.decision.cancel_unstarted()?;self.decision_turn=None;Ok(())}
 fn clear_action(&self)->Result<(),ValueError>{if self.action.is_some()||!self.decision.terminal_is_empty()||self.reading.is_some()||self.refusal.is_some()||self.reading_transferred||self.action_turn.is_some()||self.decision_turn.is_some()||self.retirement_action.is_some(){Err(refusal("original Source clock action requires recovery"))}else{Ok(())}}
 /// 📏️ Quotes the next actual host retirement action.
 pub fn retirement_demand(&self)->Result<Option<RetirementDemand>,ValueError>{if let Some((_,grant,_))=self.retirement_action{return Ok(Some(RetirementDemand{copy_bytes:grant.maximum_copy_bytes,capacity_bytes:grant.maximum_capacity_bytes,release_bytes:grant.maximum_release_bytes,depth:grant.maximum_depth}))}self.clear_action()?;if self.deadline.is_some(){return Ok(Some(RetirementDemand{copy_bytes:size_of::<Option<OriginalClockDeadline>>(),depth:1,..Default::default()}))}let Some(owner)=self.owner.as_ref()else{return Ok(None)};if owner.terminal_is_empty(){return Ok(Some(RetirementDemand{copy_bytes:size_of::<Option<Box<dyn OriginalErasedHostClock>>>(),release_bytes:owner.frame_release_bytes(),depth:1,..Default::default()}))}owner.next_demand(0).map(Some)}
 /// ⛽️ Quotes the actual selected retirement work.
 pub fn retirement_work(&self)->Result<Option<u64>,ValueError>{if let Some((_,_,work))=self.retirement_action{return Ok(Some(work))}self.clear_action()?;if self.deadline.is_some(){return Ok(Some(1))}let Some(owner)=self.owner.as_ref()else{return Ok(None)};if owner.terminal_is_empty(){Ok(Some(1))}else{owner.next_work().map(Some)}}
 /// 📥️ Lends the original reply directly to the retained host retirement owner.
 pub fn retirement_into<'reply>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{
  if self.retirement_action.is_some(){return Err(refusal("original Source clock retirement remains pending"))}self.clear_action()?;
  if self.deadline.is_none()&&self.owner.as_ref().is_some_and(|owner|!owner.terminal_is_empty()){let invocation=effect.invocation().ok_or_else(||refusal("clock retirement lacks original invocation"))?;if invocation.mode()!=semio_framework_value_control_contract::OriginalEffectCallbackMode::Receive{return Err(refusal("clock retirement changed invocation phase"))}let owner=self.owner.as_mut().expect("live clock owner");let work=owner.next_work()?;let key=(invocation.identity(),effect.grant(),work);let mut scope=reply.progress().scope(&mut self.retirement_action,key)?;let done=owner.step_into(0,effect,scope.borrow()?)?;drop(done);return Ok(scope.forwarded())}
  Ok(match self.retirement_step(effect){None=>reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))),Some(RetainedWorkPoll::Pending{..})=>reply.pending(),Some(RetainedWorkPoll::Complete(turn))=>reply.complete(turn.result)})
 }
 /// 🔁️ Recovers only the same retained host action and original grant.
 pub fn recover_retirement_into<'reply>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'reply,RetainedCloneStep,OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let key=self.retirement_action.ok_or_else(||refusal("clock retirement has no pending original action"))?;if !effect.invocation().is_some_and(|i|i.identity()==key.0&&i.mode()==semio_framework_value_control_contract::OriginalEffectCallbackMode::Recover)||effect.grant()!=key.1{return Err(refusal("clock retirement recovery changed original invocation or grant"))}let owner=self.owner.as_mut().ok_or_else(||refusal("clock retirement lost original owner"))?;let mut scope=reply.progress().scope(&mut self.retirement_action,key)?;let done=owner.recover_step_into(0,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 /// ♻️ Retires the same host or releases its paid terminal frame.
 pub fn retirement_step(&mut self,effect:&mut RetainedAllocationEffect<'_>)->Option<OriginalRetirementPoll>{if self.retirement_action.is_some(){return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(refusal("clock retirement requires original recovery"))),work:0}))}if let Err(error)=self.clear_action(){return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))}if self.deadline.is_some(){let demand=RetirementDemand{copy_bytes:size_of::<Option<OriginalClockDeadline>>(),depth:1,..Default::default()};let remaining=match effect.remaining_work_units(){Ok(work)=>work,Err(error)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))};if remaining==0||!semio_framework_value_control_contract::retained_clone_grant_admits(effect.grant(),demand){return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(refusal("original Source deadline release exceeded its Work grant"))),work:1})),Err(error)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))}self.deadline=None;return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}))}let owner=self.owner.as_mut()?;if !owner.terminal_is_empty(){let remaining=match effect.remaining_work_units(){Ok(work)=>work,Err(error)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))};let grant=effect.grant();let mut selected=match effect.reborrow(grant,remaining){Ok(selected)=>selected,Err(error)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))};return Some(owner.step(0,&mut selected))}let released=owner.frame_release_bytes();let copied=size_of::<Option<Box<dyn OriginalErasedHostClock>>>();let grant=effect.grant();let remaining=match effect.remaining_work_units(){Ok(work)=>work,Err(error)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))};if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<copied||grant.maximum_release_bytes<released||remaining==0{return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(refusal("original Source clock release exceeded its Work grant"))),work:1})),Err(error)=>return Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(OriginalRetirementFailure::from_primary(error)),work:0}))}drop(self.owner.take());Some(RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:copied,released_bytes:released,..Default::default()})),work:1}))}
}
impl Default for OriginalSourceClock{fn default()->Self{Self::new()}}
impl Drop for OriginalSourceClock{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Source clock requires paid return")}}
